import * as fs from "fs";

const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

const [first, second] = input;
const [n, k] = first.split(" ").map(Number);
const a = second.split(" ").map(Number);

// 尺取り法: 右端を 1 つずつ伸ばし、和が K を超えたら左端を縮める
let left = 0;
let sum = 0;
let best = 0;
for (let right = 0; right < n; right++) {
  sum += a[right];
  while (sum > k) {
    sum -= a[left];
    left++;
  }
  best = Math.max(best, right - left + 1);
}
console.log(best);
